1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	// An item surcharge hits every item the predicate accepts, charging its rate
89	// against that item's own base premium.
90	interface ItemSurcharge {
91	  appliesTo: (item: Item) => boolean;
92	  rate: number;
93	}
94	
95	const ITEM_SURCHARGES: ItemSurcharge[] = [
96	  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
97	  {
98	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
99	    rate: 0.3,
100	  },
101	];
102	
103	const itemSurchargeOf = (items: Item[], { appliesTo, rate }: ItemSurcharge): number =>
104	  items
105	    .filter(appliesTo)
106	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
107	
108	// Item-specific modifiers apply to the affected item's own base premium.
109	const itemModifiersOf = (items: Item[]): number =>
110	  ITEM_SURCHARGES.reduce(
111	    (sum, surcharge) => sum + itemSurchargeOf(items, surcharge),
112	    0,
113	  );
114	
115	const LOYALTY_DISCOUNT_RATE = -0.2;
116	
117	const LOYALTY_YEARS_THRESHOLD = 2;
118	
119	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
120	
121	// The context a policy-wide modifier is judged against: who the customer is,
122	// and how many quotes they have already been given in this scenario.
123	interface PolicyContext {
124	  customer: Customer;
125	  precedingQuotes: number;
126	}
127	
128	// A policy modifier hits the whole policy when the predicate accepts it,
129	// charging its rate against the policy base premium. Discounts are negative
130	// rates, so surcharges and discounts sum uniformly.
131	interface PolicyModifier {
132	  appliesTo: (context: PolicyContext) => boolean;
133	  rate: number;
134	}
135	
136	const POLICY_MODIFIERS: PolicyModifier[] = [
137	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
138	  {
139	    appliesTo: ({ customer }) =>
140	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
141	    rate: LOYALTY_DISCOUNT_RATE,
142	  },
143	  {
144	    appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
145	    rate: FOLLOW_UP_DISCOUNT_RATE,
146	  },
147	];
148	
149	// Policy-wide modifiers apply to the policy base premium, so they are computed
150	// from the base alone — item-specific modifiers are not part of their base.
151	const policyModifiersOf = (policyBase: number, context: PolicyContext): number =>
152	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
153	    (sum, { rate }) => sum + policyBase * rate,
154	    0,
155	  );
156	
157	const quote = ({ items }: QuoteStep, context: PolicyContext): QuoteResult => {
158	  const policyBase = policyBasePremiumOf(items);
159	
160	  const premiumBeforeRounding =
161	    policyBase +
162	    itemModifiersOf(items) +
163	    policyModifiersOf(policyBase, context) +
164	    PROCESSING_FEE;
165	
166	  return { premium: Math.ceil(premiumBeforeRounding) };
167	};
168	
169	const runStep = (step: Step, context: PolicyContext): StepResult => {
170	  if (step.op === "quote") return quote(step, context);
171	
172	  throw new Error(`unsupported step: ${step.op}`);
173	};
174	
175	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
176	  const results: StepResult[] = [];
177	
178	  let precedingQuotes = 0;
179	
180	  for (const step of steps) {
181	    results.push(runStep(step, { customer, precedingQuotes }));
182	
183	    if (step.op === "quote") precedingQuotes += 1;
184	  }
185	
186	  return { results };
187	};
