// One surcharge, totalled across every item it accepts.
const surchargeAcrossItems = (
  items: Item[],
  { appliesTo, rate }: ItemSurcharge,
): number =>
  items
    .filter(appliesTo)
    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);

// Item-specific surcharges apply to the affected item's own base premium.
const itemSurchargesOf = (items: Item[]): number =>
  ITEM_SURCHARGES.reduce(
    (sum, surcharge) => sum + surchargeAcrossItems(items, surcharge),
    0,
  );
